def transform(grid):
    h, w = len(grid), len(grid[0])
    clues = {}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value:
                key = (r - c) % 1000000
                clues[key] = value
    # The clue diagonals define a repeating sequence along r-c. Infer the
    # period from the number of distinct clue colors and map each residue.
    colors = list(dict.fromkeys(v for row in grid for v in row if v))
    period = len(colors)
    mapping = {}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value:
                mapping[(r-c) % period] = value
    return [[mapping[(r-c) % period] for c in range(w)] for r in range(h)]
